def search(lst):
    count_dict = {}
    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    max_num = -1
    for num in count_dict:
        if num > 0 and count_dict[num] >= num and num > max_num:
            max_num = num

    return max_num

# Test cases
print(search([4, 1, 2, 2, 3, 1]))  # Output: 2
print(search([1, 2, 2, 3, 3, 3, 4, 4, 4]))  # Output: 3
print(search([5, 5, 4, 4, 4]))  # Output: -1

def search(lst):
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    max_num = max(lst)
    for i in range(max_num, 0, -1):
        if freq.get(i, 0) >= i:
            return i
    return -1

