    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    max_num = max(lst)
    for i in range(max_num, 0, -1):
        if freq.get(i, 0) >= i:
            return i
    return -1

# Test cases
