def is_simple_power(x, n):
    if x < 1:
        return False
    log_x = 0
    temp = x
    while temp >= n:
        temp /= n
        log_x += 1
    return temp == 1 and log_x == int(log_x)

def is_simple_power(x, n):
    if x < 1:
        return False
    log_value = 0
    while x >= n ** log_value:
        log_value += 1
    return n ** (log_value - 1) == x

