def get_max_triples(n):
    def get_value(i):
        return i * i - i + 1

    a = [get_value(i) for i in range(1, n + 1)]
    count = 0

    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count

